INT_MAX = 2**31 - 1
INT_MIN = -2**31

def my_atoi(s):
    i, n = 0, len(s)
    while i < n and s[i] == ' ':
        i += 1                                          # skip leading whitespace
    sign = 1
    if i < n and s[i] in '+-':
        if s[i] == '-':
            sign = -1
        i += 1
    result = 0
    while i < n and s[i].isdigit():
        digit = int(s[i])
        if result > (INT_MAX - digit) // 10:
            return INT_MAX if sign == 1 else INT_MIN         # this digit would overflow, clamp and stop right away
        result = result * 10 + digit
        i += 1
    return sign * result


